import subprocess
import os


def execute(runtime_path: str, agent, state: dict) -> dict:
    """Clean up any previous jc installation to ensure fresh test."""
    result = {"cleanup": []}

    # Try to uninstall jc if it exists
    try:
        subprocess.run(
            ["pip", "uninstall", "jc", "-y"],
            capture_output=True,
            text=True,
            timeout=60
        )
        result["cleanup"].append("Uninstalled existing jc package")
    except Exception as e:
        result["cleanup"].append(f"No existing jc to uninstall: {e}")

    # Clean the runtime directory
    for item in os.listdir(runtime_path):
        item_path = os.path.join(runtime_path, item)
        if os.path.isdir(item_path):
            try:
                subprocess.run(["rm", "-rf", item_path], timeout=30)
                result["cleanup"].append(f"Removed directory: {item}")
            except Exception:
                pass

    return result

import os


def execute(runtime_path: str, agent, state: dict) -> dict:
    """Evaluate the simple math task."""
    result_file = os.path.join(runtime_path, "result.txt")

    # Expected answer: sum of primes 1-100 = 1060
    expected = 1060

    if not os.path.exists(result_file):
        return {
            "score": 0,
            "error": "result.txt not found",
            "expected": expected
        }

    try:
        with open(result_file, 'r') as f:
            content = f.read().strip()
            answer = int(content)
    except (ValueError, IOError) as e:
        return {
            "score": 0,
            "error": f"Could not read answer: {e}",
            "expected": expected
        }

    if answer == expected:
        return {
            "score": 100,
            "answer": answer,
            "expected": expected,
            "comment": "Perfect!"
        }
    else:
        # Partial credit based on how close
        diff = abs(answer - expected)
        if diff < 10:
            score = 80
        elif diff < 50:
            score = 50
        elif diff < 100:
            score = 25
        else:
            score = 0

        return {
            "score": score,
            "answer": answer,
            "expected": expected,
            "difference": diff,
            "comment": "Incorrect answer"
        }

